-- Exact v1 draft match encoded independently of checkout line endings. Approved and owner-edited text stays untouched.
INSERT OR IGNORE INTO content_versions(id,value,actor) SELECT 'migration0009-before-photo-deferral',value,'system:photo-deferral' FROM settings WHERE key='site' AND COALESCE(json_extract(value,'$.policiesApproved'),0)=0 AND hex(replace(json_extract(value,'$.privacyPolicy'),char(13),''))='';
INSERT OR IGNORE INTO content_media_refs(owner_key,media_id) SELECT id,json_extract(value,'$.heroMediaId') FROM content_versions WHERE id='migration0009-before-photo-deferral' AND json_extract(value,'$.heroMediaId') IS NOT NULL;
UPDATE settings SET value=json_set(value,'$.privacyPolicy',CAST(X'' AS TEXT)),revision=revision+1 WHERE key='site' AND COALESCE(json_extract(value,'$.policiesApproved'),0)=0 AND hex(replace(json_extract(value,'$.privacyPolicy'),char(13),''))='';
